    print(nm, "heads with largest A>B guess attention:", [(f"L{l}h{h}", round(float(dG[l,h]),3), round(float(G[idx,0,l,h].mean()),3)) for l,h in [divmod(o,4) for o in np.argsort(-dG.ravel())[:5]]])
